import Redis from "ioredis";

interface BucketState {
  tokens: number;
  lastRefill: number;
}

interface RateLimiterConfig {
  capacity: number; // max tokens in the bucket
  refillRate: number; // tokens added per second
}

export class RateLimiter {
  private readonly redis: Redis;
  private readonly capacity: number;
  private readonly refillRate: number;

  constructor(redis: Redis, config: RateLimiterConfig) {
    this.redis = redis;
    this.capacity = config.capacity;
    this.refillRate = config.refillRate;
  }

  async allow(clientId: string): Promise<boolean> {
    const key = `rl:${clientId}`;
    const now = Date.now();

    const raw = await this.redis.hgetall(key);
    let tokens: number;
    let lastRefill: number;

    if (raw && raw.tokens !== undefined && raw.lastRefill !== undefined) {
      tokens = parseFloat(raw.tokens);
      lastRefill = parseFloat(raw.lastRefill);
    } else {
      tokens = this.capacity;
      lastRefill = now;
    }

    // Refill based on elapsed time since the last write.
    const elapsedSeconds = (now - lastRefill) / 1000;
    tokens = Math.min(this.capacity, tokens + elapsedSeconds * this.refillRate);
    lastRefill = now;

    let allowed: boolean;
    if (tokens >= 1) {
      tokens -= 1;
      allowed = true;
    } else {
      allowed = false;
    }

    // Persist the updated bucket state on every request (hot path).
    await this.redis.hset(key, {
      tokens: tokens.toString(),
      lastRefill: lastRefill.toString(),
    });

    return allowed;
  }
}
